mapper.select:
SELECT id, title, summary, category, event_type, edition_label, organizer, location, audience_scope, audience_summary, registration_mode, participant_mode, capacity, capacity_unit, cover_attachment_id, publish_status, start_time, end_time, start_precision, end_precision, time_description, registration_start, registration_end, registration_start_precision, registration_end_precision, exam_date, exam_date_end, official_url, comment_count, like_count, view_count, published_at
FROM exam_info
WHERE publish_status = 1
  AND deleted_at IS NULL

    AND category = #{category}


    AND (
        title LIKE CONCAT('%', #{keyword}, '%')
        OR content LIKE CONCAT('%', #{keyword}, '%')
        OR official_url LIKE CONCAT('%', #{keyword}, '%')
    )


    AND id < #{lastId}

ORDER BY id DESC
LIMIT #{limit}

SELECT COALESCE(view_count, 0)
FROM exam_info
WHERE id = #{id}

mapper.update:
UPDATE exam_info
SET view_count = COALESCE(view_count, 0) + #{delta}
WHERE id = #{id}

mapper.select:
SELECT id, title, summary, category, event_type, edition_label, publish_status,
    start_time, start_precision, end_time, end_precision, registration_mode, updated_at
FROM exam_info WHERE deleted_at IS NULL

    AND (title LIKE CONCAT('%', #{query.keyword}, '%') OR edition_label LIKE CONCAT('%', #{query.keyword}, '%'))

AND category = #{query.category}
AND event_type = #{query.eventType}
AND publish_status = #{query.publishStatus}
AND id < #{lastId}
ORDER BY id DESC LIMIT #{limit}

mapper.update:
UPDATE exam_info SET publish_status = 3, status = 0, is_pinned = FALSE,
    cancelled_at = NOW(), cancel_reason = #{reason}
WHERE id = #{id} AND publish_status = 1 AND deleted_at IS NULL
